import heapq

def match(orders):
    trades = []
    book = {}  # id -> dict(side, price, qty, seq, active)
    buy_heap = []   # entries: (-price, seq, id)
    sell_heap = []  # entries: (price, seq, id)

    def push_buy(order_id):
        info = book[order_id]
        heapq.heappush(buy_heap, (-info['price'], info['seq'], order_id))

    def push_sell(order_id):
        info = book[order_id]
        heapq.heappush(sell_heap, (info['price'], info['seq'], order_id))

    for idx, order in enumerate(orders):
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            if oid in book and book[oid]['active'] and book[oid]['qty'] > 0:
                book[oid]['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        remaining = qty

        if side == 'buy':
            # match against sell_heap
            while remaining > 0 and sell_heap:
                top_price, top_seq, top_id = sell_heap[0]
                info = book.get(top_id)
                if info is None or not info['active'] or info['qty'] <= 0:
                    heapq.heappop(sell_heap)
                    continue
                resting_price = info['price']
                if typ != 'market' and resting_price > price:
                    break
                # pop it
                heapq.heappop(sell_heap)
                trade_qty = min(remaining, info['qty'])
                trades.append([oid, top_id, resting_price, trade_qty])
                remaining -= trade_qty
                info['qty'] -= trade_qty
                if info['qty'] <= 0:
                    info['active'] = False
                else:
                    heapq.heappush(sell_heap, (top_price, top_seq, top_id))
            if typ == 'limit' and remaining > 0:
                book[oid] = {'side': 'buy', 'price': price, 'qty': remaining, 'seq': idx, 'active': True}
                push_buy(oid)
        else:
            # side == 'sell', match against buy_heap
            while remaining > 0 and buy_heap:
                top_negprice, top_seq, top_id = buy_heap[0]
                info = book.get(top_id)
                if info is None or not info['active'] or info['qty'] <= 0:
                    heapq.heappop(buy_heap)
                    continue
                resting_price = info['price']
                if typ != 'market' and resting_price < price:
                    break
                heapq.heappop(buy_heap)
                trade_qty = min(remaining, info['qty'])
                trades.append([top_id, oid, resting_price, trade_qty])
                remaining -= trade_qty
                info['qty'] -= trade_qty
                if info['qty'] <= 0:
                    info['active'] = False
                else:
                    heapq.heappush(buy_heap, (top_negprice, top_seq, top_id))
            if typ == 'limit' and remaining > 0:
                book[oid] = {'side': 'sell', 'price': price, 'qty': remaining, 'seq': idx, 'active': True}
                push_sell(oid)

    return trades

